D['vidya']=dict(desc='Vidyā Lakṣmī, Lakṣmī of knowledge: her white-clad form with lotus and book, how she differs from Sarasvatī, “knowledge is the greatest wealth”, Lakṣmī Hayagrīva, vidyārambha and akṣarābhyāsa, and the folk saying that Lakṣmī and Sarasvatī do not live together.',
 tag='Lakṣmī of knowledge',fwq=("Isn't knowledge Sarasvatī's?","Sarasvatī is knowledge itself. Vidyā Lakṣmī is knowledge as your fortune.") ,
 fw=['<b>Vidyā</b> means knowledge, learning, skill. Vidyā Lakṣmī, clad in white with a lotus and a book, is Lakṣmī as the blessing of education: the wealth that no thief can take and that grows when shared.',
     'This guide asks how she differs from Sarasvatī, follows the old verses that call knowledge the greatest wealth, and visits the rites where children write their first letter.'],
 pages=[('glance','AT A GLANCE','Vidyā Lakṣmī on one page',[('Name','Vidyā Lakṣmī, “Lakṣmī of knowledge”'),('Gift','Education, skill, wisdom and the success they bring'),('Form','White sari; four arms holding lotuses (and in many images a book); boon and fear-not gestures'),('Seated','On a lotus, like the other Lakṣmīs'),('Prayed to','By students and teachers, before exams and new studies')],("White, like Sarasvatī?","Yes, the colour of learning. But she still sits on Lakṣmī's lotus.")),
  ('sarasvati','NOT SARASVATĪ','Two goddesses, one gift',[('Sarasvatī','Goddess of knowledge, speech, music and the arts; Brahmā’s consort'),('Vidyā Lakṣmī','Lakṣmī giving knowledge as a form of fortune'),('Difference','Sarasvatī is learning itself; Vidyā Lakṣmī is learning as wealth, opportunity and good luck'),('Navarātri','In the South, the last three nights are for Sarasvatī, after Durgā and Lakṣmī')]),
  ('greatest','THE GREATEST WEALTH','Old sayings',[('Vidyā dhanam','“The wealth of knowledge is the chief of all wealth”: a well-known saying'),('Cannot be stolen','No thief, king, brother or burden can take it, and it grows when given'),('Bhartṛhari','His Nītiśataka calls learning a man’s finest beauty and hidden treasure'),('Abroad','Knowledge is a friend in foreign lands')],("Grows when you give it away?","Teach someone something. You'll know it better yourself.")),
  ('hayagriva','LAKṢMĪ HAYAGRĪVA','The horse-headed teacher',[('Hayagrīva','Viṣṇu’s horse-headed form, who recovered the Vedas from demons'),('With Lakṣmī','Lakṣmī Hayagrīva, Lord of learning with Lakṣmī on his lap'),('Vedānta Deśika','The 13th–14th century teacher was a great devotee; his Hayagrīva Stotra is chanted by students'),('Mysuru','The Parakāla Maṭha in Mysuru keeps Lakṣmī Hayagrīva as its deity')]),
  ('vidyarambha','THE FIRST LETTER','Vidyārambha and akṣarābhyāsa',[('Vidyārambha','On Vijayadaśamī, small children write their first letters, often “Om” or “Śrī”, in rice or sand'),('Kerala · Karnataka','Huge vidyārambham ceremonies at Thunchan Parambu in Kerala and Kollūr Mūkāmbikā in coastal Karnataka'),('Akṣarābhyāsa','Telugu and Kannada lands, often at Basara or at home'),('Śrī first','Many begin with “Śrī”: learning begins with Lakṣmī’s name')]),
  ('stotram','HER VERSE','In the Aṣṭalakṣmī Stotram',[('Theme','Her verse calls her the giver of knowledge, worshipped by gods, destroyer of the darkness of ignorance'),('Tone','Bright, like a morning prayer'),('Refrain','It asks her to protect the singer always'),('Use','Sung by students in the morning and before exams')]),
  ('together','DO THEY LIVE TOGETHER?','A folk saying',[('Saying','A popular quip: Lakṣmī and Sarasvatī never live in the same house; the rich are not learned, the learned not rich'),('Vidyā Lakṣmī','The very idea of Vidyā Lakṣmī answers the quip: knowledge can be fortune'),('Kālidāsa','Poets praised kings who had both'),('Today','Education is the surest path out of poverty')],("So which is true?","The saying is a grumble. Vidyā Lakṣmī is the hope.")),
  ('teachers','TEACHERS AND SCHOOLS','Where she lives',[('Guru','Tradition: honouring teachers pleases her'),('Books','Books are not stepped on, and are touched to the forehead if dropped'),('Āyudha pūjā','Books and tools are worshipped on Mahānavamī'),('Sharing','Teaching is the best use of learning')]),
  ('meaning','WHAT SHE TEACHES','The wealth no one can steal',[('Learn','The surest wealth'),('Share','It grows when given'),('Respect','Teachers, books and tools'),('Use','Knowledge brings fortune when put to work')]),
 ],
 end=[('Who','Lakṣmī of knowledge, white-clad, with lotus and book'),('Not Sarasvatī','Learning as fortune, not learning itself'),('Sayings','Knowledge, the chief of all wealth'),('Rites','Vidyārambha, akṣarābhyāsa, āyudha pūjā'),('Lesson','Learn, share and honour teachers')],endq=("One line?","The only wealth that grows when you give it away."),
 src='Bhartṛhari, Nītiśataka (on learning); common subhāṣita “vidyādhanaṃ sarvadhanapradhānam”; Vedānta Deśika, Hayagrīva Stotra; Parakāla Maṭha, Mysuru; Kerala vidyārambham customs (Kollūr, Thunchan Parambu); Basara Jñāna Sarasvatī temple.',
 unv='The book in her hands appears in some images but not all; the folk saying about Lakṣmī and Sarasvatī has no single source.',
 EX={'glance':['Vidyā Lakṣmī often surprises people who think of Lakṣmī only as money. Her white sari and the book in many of her images show her close to Sarasvatī; her lotus and the boon gesture keep her Lakṣmī.','She is the form most prayed to by students, and her picture sits on many study desks in South Indian homes, especially at exam time.'],
  'sarasvati':['The distinction is subtle but useful. Sarasvatī is the Goddess of knowledge itself: speech, music, learning, the arts. Vidyā Lakṣmī is the fortune of having learning: the opportunities, respect and livelihood it brings.','Many South Indian families divide Navarātri into three groups of three nights, Durgā, Lakṣmī, Sarasvatī, and end with Sarasvatī Pūjā and Āyudha Pūjā before Vijayadaśamī.'],
  'greatest':['The saying that knowledge is the greatest wealth appears in many subhāṣita collections in slightly different forms. One version lists the reasons: it cannot be stolen by thieves, taken by kings, divided among brothers, and it is never a burden; and when spent, it increases.','Bhartṛhari’s Nītiśataka has a famous verse praising learning as a person’s greatest beauty, a hidden treasure, the giver of enjoyment, fame and happiness, a teacher of teachers, a friend abroad, and the highest deity.'],
  'hayagriva':['Hayagrīva, the horse-headed form of Viṣṇu, recovered the stolen Vedas in a Purāṇic story and became the patron of learning in Śrīvaiṣṇava tradition. Shown with Lakṣmī on his lap, he is Lakṣmī Hayagrīva.','Vedānta Deśika, the great Śrīvaiṣṇava philosopher-poet, wrote a famous Hayagrīva Stotra that students still recite before exams. The Brahmatantra Svatantra Parakāla Maṭha, with its main seat in Mysuru, worships Lakṣmī Hayagrīva.'],
  'vidyarambha':['Vidyārambha, the beginning of learning, is one of India’s loveliest rites. A child sits on a parent’s or teacher’s lap and traces the first letters in a tray of rice, then on the tongue with a gold ring. In Kerala, thousands of children do this on Vijayadaśamī at temples and at Thunchan Parambu, home of the poet Ezhuthachan.','In Karnataka, Kollūr Mūkāmbikā draws families from across the South for akṣarābhyāsa, and in Telangana the Jñāna Sarasvatī temple at Basara is famous for it.'],
  'stotram':['Her verse in the Stotram speaks of dispelling ignorance like darkness. It is the verse most recited on its own by students.','We describe rather than reproduce it.'],
  'together':['The folk saying that Lakṣmī and Sarasvatī do not share a home is a wry comment on the poor scholar and the unlettered rich man, a common figure in Sanskrit and regional literature.','Vidyā Lakṣmī is, in a way, the tradition’s answer: knowledge itself can be fortune, and the best fortune is the kind that comes through learning.'],
  'teachers':['Respect for learning shows in small customs: books are never stepped on, and if one falls it is lifted and touched to the forehead. On Āyudha Pūjā, books, pens, tools, vehicles and computers are cleaned, decorated and worshipped.','The guru is honoured as the giver of vidyā, so pleasing the teacher is pleasing Vidyā Lakṣmī.'],
  'meaning':['Vidyā Lakṣmī’s lesson is practical and hopeful: learning is the most secure wealth, the one most able to lift a family across generations.','And unlike every other wealth, it grows when given away.']})
D['dhana']=dict(desc='Dhana Lakṣmī, Lakṣmī of money: her six-armed red form with a pot of gold, discus and conch; Kubera and the Tirumala debt, Dhanteras and Dīpāvalī Lakṣmī Pūjā, Ādi Śaṅkara’s Kanakadhārā, wealth earned by dharma, and giving.',
 tag='Lakṣmī of money and wealth',fwq=("Finally, money!","The last of eight. Money is a real gift; it's just not the only one.") ,
 fw=['<b>Dhana</b> means money, riches, treasure. Dhana Lakṣmī holds a pot overflowing with gold coins. She is the form most people think of when they hear “Lakṣmī”, and the one honoured on Dhanteras and Dīpāvalī in shops and homes across India.',
     'This last guide looks at money the traditional way: as a real good, to be earned by right means, kept with care and given away generously. It ends the series where it began, with the Goddess who gives all eight.'],
 pages=[('glance','AT A GLANCE','Dhana Lakṣmī on one page',[('Name','Dhana Lakṣmī, “Lakṣmī of wealth”'),('Gift','Money, gold, prosperity and freedom from debt'),('Form','Red sari; six arms: discus, conch, a pot of gold or nectar, bow and arrow, a lotus; one hand pouring coins'),('Seen at','The top of the Chennai Aṣṭalakṣmī temple, under the śikhara; shop altars everywhere'),('Days','Fridays, Dhanteras, Dīpāvalī, Akṣaya Tṛtīyā')],("Is it wrong to pray for money?","No. Artha, wealth, is one of the four goals of life. Earn it rightly.")),
  ('artha','ARTHA','Wealth as a goal of life',[('Four goals','Dharma, artha, kāma, mokṣa: right living, wealth, pleasure, freedom'),('Artha','A legitimate goal, not a sin'),('Condition','Wealth must be earned and used within dharma'),('Arthaśāstra','Kauṭilya’s treatise on statecraft and economy: wealth is the root of dharma and kāma')],("Kauṭilya said money matters?","He said a state without wealth can't protect anyone. Practical man.")),
  ('kubera','KUBERA AND LAKṢMĪ','The treasurer and the Goddess',[('Kubera','Lord of riches, guardian of the north, keeper of the gods’ treasury'),('Different','Kubera guards wealth; Lakṣmī is its source and grace'),('Tirumala','Śrīnivāsa borrowed from Kubera for his wedding to Padmāvatī; devotees’ offerings repay the debt'),('Together','Lakṣmī–Kubera pūjā on Dīpāvalī in many homes')]),
  ('kanakadhara','THE RAIN OF GOLD','Ādi Śaṅkara and the poor woman',[('The story','As a boy begging alms, Śaṅkara came to a poor woman’s home; she had only a dried āmalaka fruit, and gave it'),('His hymn','Moved, he sang to Lakṣmī: the Kanakadhārā Stotram'),('The gold','Golden āmalaka fruits rained on her house'),('Place','Tradition places it at Kālaḍi, Kerala')],None,'<div class="key">Verse by verse: <a href="/bhakti/devi/kanakadhara-stotram/">Kanakadhārā Stotram</a></div>'),
  ('dhanteras','DHANTERAS AND DĪPĀVALĪ','Her great days',[('Dhanteras','Dhana-trayodaśī, two days before Dīpāvalī: buy gold, silver or new vessels; Dhanvantari, the god of medicine, is also honoured'),('Lakṣmī Pūjā','On Dīpāvalī’s new moon, with lamps everywhere so she can find her way'),('Account books','Traders begin new books (cōpḍā pūjan) with her blessing'),('Akṣaya Tṛtīyā','A spring day when gold bought is said never to diminish')]),
  ('stotram','HER VERSE','In the Aṣṭalakṣmī Stotram',[('Theme','Her verse rings with the sound of drums and conches and calls her the giver of wealth'),('Last','It is the eighth and final verse of the hymn'),('Refrain','It asks her to protect the singer always'),('Use','In shops each morning, and at Dīpāvalī')]),
  ('rightly','EARN IT RIGHTLY','Dharma and wealth',[('Rule','Wealth gained by wrong means brings Alakṣmī with it'),('Gītā','Work without greed for its fruit (2.47)'),('Īśa Upaniṣad','Enjoy by renouncing; do not covet anyone’s wealth (verse 1)'),('Debt','Freedom from debt is itself counted a blessing')],("What's Alakṣmī?","Misfortune. She follows wealth gained by cheating.")),
  ('giving','GIVING','The best use of wealth',[('Dāna','Giving is the noblest use of wealth'),('Three fates','A saying: wealth is given, enjoyed or lost; if not the first two, then the third'),('Annadāna','Feeding people is the highest gift'),('Śaṅkara','The poor woman gave her only fruit, and gold rained down')]),
  ('meaning','WHAT SHE TEACHES','Money in its place',[('Money is good','A real gift, not a sin'),('Earn rightly','Within dharma'),('Keep carefully','Avoid waste and debt'),('Give freely','Wealth that flows stays'),('One of eight','Without the other seven it is not enough')]),
 ],
 end=[('Who','Lakṣmī of money and wealth'),('Theory','Artha, one of the four goals; Kauṭilya'),('Stories','Kubera’s loan; Śaṅkara’s rain of gold'),('Days','Dhanteras, Dīpāvalī, Akṣaya Tṛtīyā'),('Lesson','Earn rightly, keep carefully, give freely')],endq=("One line to end the series?","Eight Lakṣmīs, one Goddess. Money is the last of her gifts, not the first."),
 src='Kauṭilya, Arthaśāstra 1.7; Bhagavad Gītā 2.47; Īśa Upaniṣad 1; Bhartṛhari, Nītiśataka (three fates of wealth); Śaṅkara-digvijaya traditions (Kanakadhārā); Tirumala tradition on Kubera’s loan; Aṣṭalakṣmī temple, Chennai (Dhana Lakṣmī under the śikhara).',
 unv='Her weapons vary by image; the Kanakadhārā story is from hagiography; Dīpāvalī dates differ between calendars.',
 EX={'glance':['Dhana Lakṣmī is the Lakṣmī of shop altars, cash boxes and account books. Her pot of gold coins and her pouring hand appear on calendars in every market in India.','In the Chennai Aṣṭalakṣmī temple she is placed at the very top, under the śikhara: the last shrine pilgrims reach as they climb.'],
  'artha':['Indian thought never treated wealth as evil in itself. Artha, material prosperity, is one of the puruṣārthas, the four goals of human life, alongside dharma, kāma and mokṣa. A householder is expected to earn, save, support the family and give.','Kauṭilya’s Arthaśāstra goes further: it says artha is the chief of the three worldly goals, because dharma and kāma depend on it. The traditional balance comes from the other side: artha must be pursued within dharma.'],
  'kubera':['Kubera, half-brother of Rāvaṇa, is the yakṣa king and treasurer of the gods, guardian of the north. In popular worship he is often paired with Lakṣmī: she brings wealth, he keeps it safe.','The Tirumala legend of Śrīnivāsa borrowing from Kubera to pay for his wedding is why devotees speak of their offerings as helping the Lord repay his loan, a tender joke at the heart of the richest temple in India.'],
  'kanakadhara':['The Kanakadhārā story is one of the best loved of Ādi Śaṅkara’s legends. As a young brahmacārī he went begging and stood at a poor woman’s door. She had nothing to give except one dried āmalaka (Indian gooseberry), and gave it with shame and love.','Śaṅkara’s hymn to Lakṣmī, whose verses we have explained one by one on this site, moved the Goddess to rain golden āmalakas on the house. The lesson is about the giver: the poor woman’s gift, not the boy’s hymn, is what Lakṣmī answered.'],
  'dhanteras':['Dhanteras is also the day of Dhanvantari, the physician of the gods who rose from the churning holding the pot of nectar. In India it is now National Ayurveda Day. Buying a new utensil or gold on this day is believed to invite Lakṣmī.','On Dīpāvalī night, homes are lit with lamps so the Goddess can enter. Merchants in western and northern India close their old account books and open new ones with a Lakṣmī pūjā, writing “Śubh” and “Lābh”.'],
  'stotram':['Her verse closes the Aṣṭalakṣmī Stotram with a crescendo of drums and conches. In many shops it is played at opening time.','We describe rather than reproduce it.'],
  'rightly':['The Īśa Upaniṣad’s first verse, much quoted by Gandhi, says: all this is pervaded by the Lord; enjoy it by giving up; do not covet anyone’s wealth. It is a compact ethic of money.','Tradition warns that wealth earned by cheating brings Alakṣmī, misfortune, with it. Freedom from debt, ṛṇa-mukti, is itself often counted among Lakṣmī’s blessings.'],
  'giving':['Bhartṛhari’s famous verse says wealth has three possible fates: it is given, enjoyed or destroyed; whoever neither gives nor enjoys it will see it go the third way.','Annadāna, giving food, is called the greatest gift because it meets the most basic need, and links Dhana Lakṣmī back to Dhānya Lakṣmī, the second of the eight.'],
  'meaning':['Dhana Lakṣmī ends the series with balance. Money is good and needed; it should be earned within dharma, kept with care, and given generously.','But it is only one of eight forms. Grain, courage, dignity, family, victory and learning, and the grace of Ādi Lakṣmī behind them all, make a life truly rich.']})
for i,k in [(6,'vidya'),(7,'dhana')]: FORM(i,D[k])
